/bin/zsh -lc "node --input-type=module <<'NODE'
import fs from 'node:fs';
import crypto from 'node:crypto';
const paths = ['yss-project.yaml','AGENTS.md','CONTEXT.md','state.json','plan.md','review.json','reconciliation.json','.template-spec/process/lifecycle-registry.yaml','.template-spec/agents/digital-human-roles.yaml','.template-spec/agents/issue-tracker.md','docs/.scratch/demo/parent-ticket.md',...fs.readdirSync('approval').map(name => "'`approval/${name}`)];
const snapshot = Object.fromEntries(paths.map(path => [path, '"'sha256:' + crypto.createHash('sha256').update(fs.readFileSync(path)).digest('hex')]));
for (const path of ['entry-result.json','docs/.scratch/demo/spec.md','docs/.scratch/demo/entry-work-record.json']) if (fs.existsSync(path)) throw new Error("'`目标已存在：${path}`);
process.stdout.write(JSON.stringify(snapshot));
NODE'

/bin/zsh -lc "node --input-type=module <<'NODE'
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import assert from 'node:assert/strict';
const result = JSON.parse(fs.readFileSync('entry-result.json', 'utf8'));
const record = JSON.parse(fs.readFileSync('docs/.scratch/demo/entry-work-record.json', 'utf8'));
const specPath = 'docs/.scratch/demo/spec.md';
const spec = fs.readFileSync(specPath, 'utf8');
assert.equal(result.result, 'allowed');
assert.equal(result.verification_command, 'node scripts/verify-plan-spec-entry state.json');
assert.equal(result.exit_code, 0);
assert.equal(record.ready_for_agent, false);
assert.match(spec, /"'^status: ready-for-human$/m);
assert.match(spec, /test-data-only/);
for (const id of ['"'AC-001', 'AC-002', 'AC-003']) assert.ok(spec.includes(id));
for (const [ref, expected] of Object.entries(record.inputs)) {
  const observed = 'sha256:' + crypto.createHash('sha256').update(fs.readFileSync(ref)).digest('hex');
  assert.equal(observed, expected, "'`上游文件发生变化：${ref}`);
}
const links = [...spec.matchAll(/'"\\]\\((["'^)]+)'"\\)/g)].map(match => path.resolve(path.dirname(specPath), match[1]));
for (const link of links) assert.ok(fs.existsSync(link), "'`引用不可读：${link}`);
console.log(JSON.stringify({status:'"'passed', result:result.result, spec_status:record.spec_status, unchanged_upstream_files:Object.keys(record.inputs).length, readable_spec_links:links.length}));
NODE"

